				if fallbackResult, fallbackErr := fastMarshalData(data); fallbackErr == nil {
					return fallbackResult, nil
				}
			}
			// Try Frugal fallback
			if typecodec.Frugal {
				if fallbackResult, fallbackErr := frugalMarshalData(data); fallbackErr == nil {
					return fallbackResult, nil
				}
			}
