package client

import (
	"fmt"
	"time"

	"github.com/cloudwego/kitex/internal/client"
	"github.com/cloudwego/kitex/pkg/endpoint"
	"github.com/cloudwego/kitex/pkg/retry"
	"github.com/cloudwego/kitex/pkg/utils"
)

// UnaryOption is an option type for configuring unary RPC behavior.
type UnaryOption = client.UnaryOptions

// WithUnaryOptions applies multiple unary-specific options at once.
func WithUnaryOptions(opts UnaryOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithUnaryOptions(...)")
		o.UnaryOptions = opts
	}}
}

// WithUnaryRPCTimeout sets the RPC timeout specifically for unary calls.
// This timeout applies only to unary RPCs and does not affect streaming calls.
func WithUnaryRPCTimeout(timeout time.Duration) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRPCTimeout(%s)", timeout))
		o.UnaryOptions.RPCTimeout = &timeout
	}}
}

// WithUnaryMiddleware adds a middleware specifically for unary RPCs.
func WithUnaryMiddleware(mw endpoint.Middleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddleware(%T)", mw))
		o.UnaryOptions.Middlewares = append(o.UnaryOptions.Middlewares, mw)
	}}
}

// WithUnaryMiddlewareBuilder adds a middleware builder specifically for unary RPCs.
func WithUnaryMiddlewareBuilder(mwb endpoint.MiddlewareBuilder) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryMiddlewareBuilder(%T)", mwb))
		o.UnaryOptions.MiddlewareBuilders = append(o.UnaryOptions.MiddlewareBuilders, mwb)
	}}
}

// WithUnaryRetryPolicy sets a retry policy for a specific unary method.
// The method parameter should match the method name in the IDL.
func WithUnaryRetryPolicy(method string, policy retry.Policy) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithUnaryRetryPolicy(%s, %T)", method, policy))
		if o.UnaryOptions.RetryMethodPolicies == nil {
			o.UnaryOptions.RetryMethodPolicies = make(map[string]retry.Policy)
		}
		o.UnaryOptions.RetryMethodPolicies[method] = policy
	}}
}
