// StreamOption is an option type for configuring gRPC streaming RPC behavior.
type StreamOption = client.StreamOptions

// WithStreamOptions applies multiple streaming-specific options at once.
func WithStreamOptions(opts StreamOption) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamOptions(...)")
		o.StreamOptions = opts
	}}
}

// WithStreamRecvTimeout sets the receive timeout for streaming calls.
// This timeout applies to individual Recv() operations on the stream.
func WithStreamRecvTimeout(timeout time.Duration) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamRecvTimeout(%s)", timeout))
		o.StreamOptions.RecvTimeout = &timeout
	}}
}

// WithStreamMiddleware adds a middleware specifically for streaming RPCs.
func WithStreamMiddleware(mw endpoint.Middleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamMiddleware(%T)", mw))
		o.StreamOptions.Middlewares = append(o.StreamOptions.Middlewares, mw)
	}}
}

// WithStreamMiddlewareBuilder adds a middleware builder specifically for streaming RPCs.
func WithStreamMiddlewareBuilder(mwb endpoint.MiddlewareBuilder) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamMiddlewareBuilder(%T)", mwb))
		o.StreamOptions.MiddlewareBuilders = append(o.StreamOptions.MiddlewareBuilders, mwb)
	}}
}

// WithStreamRecvMiddleware adds a receive middleware for streaming calls.
func WithStreamRecvMiddleware(mw streamx.StreamRecvMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamRecvMiddleware(%T)", mw))
		o.StreamOptions.StreamRecvMWs = append(o.StreamOptions.StreamRecvMWs, mw)
	}}
}

// WithStreamRecvMiddlewareBuilder adds a receive middleware builder for streaming calls.
func WithStreamRecvMiddlewareBuilder(builder func(next streamx.StreamRecvMiddleware) streamx.StreamRecvMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamRecvMiddlewareBuilder(...)")
		// Build the middleware chain by wrapping
		baseMW := func(ctx interface{}, recv func() error) error {
			return recv()
		}
		mw := builder(baseMW)
		o.StreamOptions.StreamRecvMWs = append(o.StreamOptions.StreamRecvMWs, mw)
	}}
}

// WithStreamSendMiddleware adds a send middleware for streaming calls.
func WithStreamSendMiddleware(mw streamx.StreamSendMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamSendMiddleware(%T)", mw))
		o.StreamOptions.StreamSendMWs = append(o.StreamOptions.StreamSendMWs, mw)
	}}
}

// WithStreamSendMiddlewareBuilder adds a send middleware builder for streaming calls.
func WithStreamSendMiddlewareBuilder(builder func(next streamx.StreamSendMiddleware) streamx.StreamSendMiddleware) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithStreamSendMiddlewareBuilder(...)")
		// Build the middleware chain by wrapping
		baseMW := func(ctx interface{}, send func() error) error {
			return send()
		}
		mw := builder(baseMW)
		o.StreamOptions.StreamSendMWs = append(o.StreamOptions.StreamSendMWs, mw)
	}}
}

// WithStreamTransportOption sets a transport-specific option for streaming calls.
func WithStreamTransportOption(key string, value interface{}) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push(fmt.Sprintf("WithStreamTransportOption(%s, %v)", key, value))
		if o.StreamOptions.TransportOptions == nil {
			o.StreamOptions.TransportOptions = make(map[string]interface{})
		}
		o.StreamOptions.TransportOptions[key] = value
	}}
}
